const express = require('express');
const router = express.Router();

const { auth } = require('../middlewares/employee.middleware');
const employeeController = require('../controllers/employee.controller');

// Employee submits resignation
router.post('/resign', auth, employeeController.newUserResign);

// Employee submits exit questionnaire
router.post('/responses', auth, employeeController.submitExitResponses);

module.exports = router;
